 if(count>kTableMessageBatchMax) {if(report!=NULL) {report->refused=1;
 report->reason=SCHEMA_TABLE_BATCH_TOO_LARGE;
 }return -1;
 }
 if(buffer==NULL || capacity<0) return -1;
